) AS v(category_slug,slug,title_ar,client_guidance,freelancer_guidance)
JOIN categories c ON c.slug=v.category_slug
ON CONFLICT (slug) DO NOTHING;
CREATE INDEX IF NOT EXISTS idx_marketplace_services_category_active
 ON services(category_id,id) WHERE active=TRUE;
COMMIT;
